62	  import   --source-dir 源目录 --asset-id 编号 [--asset-id 编号...]
63	                                                              [--data-dir 目录]
64	
65	通用参数:
66	  --data-dir 目录   本地数据目录，默认 ".caretrack"；不同目录数据互不影响，
67	                    目录不存在时会在首次成功写入时自动初始化
68	
69	业务规则:
70	  - 资产编号、名称、位置均不能为空；同一数据目录内资产编号唯一，新资产为“可用”。
71	  - 每项资产最多有一张未关闭工单；未知资产、空故障描述、资产已有未关闭工单时
72	    报修失败，不改变状态与履历。
73	  - --request-id 由调用方提供且非空，仅用于同一数据目录内的报修去重，不作为
74	    资产或工单编号：相同标识、资产、描述再次提交返回原工单及当前状态，不新增
75	    记录；同一标识搭配不同资产或描述将被拒绝；原工单关闭或取消后重放仍返回原工单，
76	    不重开旧单，也不影响新单。
77	  - 仅未关闭工单可派工：没有负责人时首次派工，已有负责人时转派给不同人员。
78	    维修人员标识只是本地文本记录（非人员账户），与派工说明均不能为空；
79	    成功后保存负责人、变更时间与说明，并追加一条含原负责人（首次派工为
80	    “未派工”）、新负责人及说明的派工履历。派工不创建工单、不消耗工单编号，
81	    不改变资产状态或报修请求绑定；未知工单、空人员或说明、重复派给当前
82	    人员、对已关闭或已取消工单派工均失败且不产生履历。工单关闭或取消后
83	    保留最后负责人与派工履历。
84	  - 仅未关闭工单可关闭，维修结果不能为空；未知工单、重复关闭均失败。
85	  - 仅未关闭工单可取消，取消理由不能为空；取消后工单进入“已取消”终态，保存取消
86	    理由与时间，资产恢复“可用”，可再次报修。取消不代表维修完成，不填写维修结果，
87	    不删除工单、履历或请求绑定，工单编号不回退也不复用；已取消工单不能关闭或再次
88	    取消，已关闭工单也不能取消。
89	  - 每项资产最多一个周期保养计划，建立后不可覆盖：保养内容非空，首次到期日为
90	    0001 至 9999 年的有效公历日期（YYYY-MM-DD），间隔天数为正整数；日期按日历日
91	    运算，不受时区与运行时刻影响。未知资产或已有计划时拒绝。资产详情显示保养
92	    内容、间隔与下一到期日，无计划时明确提示。
93	  - maintain 登记当前周期的保养完成：--due 所填周期到期日必须等于当前下一到期日
94	    （旧周期不能重复登记，也不能登记尚未到期的新周期），--done 实际完成日不得早于
95	    周期到期日，--result 结果非空；无计划时拒绝。成功后记录一次实际保养，下一到期
96	    日为首次到期日加整数倍间隔所得日期中严格晚于完成日的最早日期；延期跨过的
97	    周期不生成完成记录，也不改用完成日加间隔。若下一到期日超出 9999-12-31，整次
98	    拒绝。输出完成周期与下一到期日。
99	  - due 为只读查询：列出下一到期日不晚于 --date 的保养计划，显示资产编号、名称、
100	    保养内容和到期日，按到期日再按资产编号排序；无匹配明确提示。不写文件、不
101	    初始化目录、不推进计划。
102	  - 每个保养计划恰有一条含初始计划的建立履历，完成履历含周期到期日、实际完成日
103	    和结果；保养履历与维修履历按全库唯一履历序号共同展示操作时间及内容。维修中
104	    资产也可建立计划和登记完成：保养不创建或终结工单、不消耗工单编号，不改变
105	    资产状态、请求绑定或停机统计。
106	  - 备件领用与退回台账：仅未关闭工单可领用，备件编号与说明非空、数量为正整数
107	    （表示工单用量）；每次成功生成同目录唯一且不复用的领用编号（形如 P0001）
108	    并输出，同备件多次领用各自独立，领用编号用于定位记录，不用报修请求标识
109	    代替。退回按领用编号进行，作用于其所属工单，数量为正整数、理由非空，允许
110	    多次部分退回，累计不得超过该笔原数量，也不能冲减另一笔；成功显示累计退回
111	    及净量（原数量减累计退回）。未知领用编号、超额退回拒绝；超额判断不做
112	    可能整数溢出的比较。工单关闭或取消后
113	    保留领用记录与净量，不自动清零；终结后拒绝领用、退回，旧单操作不影响新单。
114	    领用编号只定位记录，各笔先后由该笔唯一领用履历的全库序号确定；有效台账
115	    允许记录数组乱序、序号间隔、时间不递增及编号大小与领用先后不一致，无需
116	    转换即可继续使用。ticket 查询按此顺序显示各笔编号、备件、原数量、累计
117	    退回及净量，并按备件编号字典序汇总净量（零值仍显示；合计为精确十进制
118	    整数，超出单笔数量范围也不回绕、不截断），无记录明确提示；history 按
119	    全库履历序号展示领用、退回的时间、工单、领用编号、备件、数量及说明或
120	    理由。领用、退回各为一次原子保存：校验、数量或编号容量不足、读写失败
121	    时保留原文件字节，不留下部分记录、不消耗编号，恢复后可重试。
122	  - downtime 为只读统计，不写文件、不初始化目录、不追加履历。--start/--end 为
123	    带时区的 RFC3339 时刻（可含小数秒），起点须早于终点；窗口包含起点、不包含
124	    终点，按实际时刻比较。停机自工单报修履历时间起，至关闭或取消履历时间止
125	    （取消前的占用同样计入）；派工、转派不另起区间；未关闭工单暂算到窗口终点，
126	    不读取运行时刻，也不改变状态。只统计工单区间与窗口的交集，窗口外及零长度
127	    不贡献；同一资产多张工单的重叠交集取并集，不直接相加。每项资产合计后向下
128	    取整为秒，并输出全部所选资产秒数之和；没有停机的资产显示零。不给 --asset-id
129	    时统计全部资产并按编号字典序排列，空库明确提示无记录并显示零合计。若所选
130	    资产任一终结工单的结束履历时间早于报修履历时间（即使该单在窗口外、结束
131	    等于开始合法），整次统计失败，指出资产与工单，不输出部分结果。
132	  - import 把源数据目录中所选资产连同全部工单、报修请求绑定、履历、保养计划与
133	    备件领用记录复制到目标目录（--data-dir）：源台账始终只读，同一台账不能导入
134	    自身；重复编号按一项处理。工单编号按源工单序号升序从目标下一序号重新分配，
135	    履历与请求绑定中的工单引用同步替换；领用编号按源领用履历序号整体排序后从
136	    目标下一序号重新分配并输出映射，退回履历中的领用引用同步更新；数量、时间
137	    精度与操作顺序保持。
138	    履历在目标最大履历序号之后按源序号顺序分配新序号，保留原操作顺序与原时间
139	    （含小数秒）。保养计划与保养履历原样复制，内容、日期及完成链接续，目标已有
140	    计划不变。资产编号在目标已存在、或所选工单的任一请求标识已在目标绑定时整批
141	    拒绝，不覆盖、不合并。导入后可用原请求标识、资产与描述重放报修，返回映射后
142	    的工单及其当前状态；再次导入同一批资产按编号冲突拒绝。任何失败（源不存在、
143	    资产不存在、台账损坏、编号或履历序号容量不足、读写失败）都整批失败，两边
144	    原文件不变，不消耗目标编号。导入的未关闭工单可继续退回备件。
145	
146	无参数、--help、-h 显示本帮助；参数错误或业务失败以非零退出码结束并说明原因。
147	参数错误退出码为 2；未知资产、上述时间异常及数据读取失败退出码为 1。
148	`
149	
150	type cmdOptions struct {
151		dataDir string
152	}
153	
154	func printHelp(w io.Writer) {
155		fmt.Fprint(w, helpText)
156	}
157	
158	func main() {
159		os.Exit(run(os.Args[1:], os.Stdout, os.Stderr))
160	}
161	
162	func run(args []string, stdout, stderr io.Writer) int {
163		if len(args) == 0 {
164			printHelp(stdout)
165			return 0
166		}
167		switch args[0] {
168		case "--help", "-h", "help":
169			if len(args) > 1 {
170				fmt.Fprintf(stderr, "%s: help 不接受额外参数\n", appName)
171				return 2
172			}
173			printHelp(stdout)
174			return 0
175		}
176	
177		var err error
178		switch args[0] {
179		case "register":
180			err = cmdRegister(args[1:], stdout)
181		case "list":
182			err = cmdList(args[1:], stdout)
183		case "detail":
184			err = cmdDetail(args[1:], stdout)
185		case "report":
186			err = cmdReport(args[1:], stdout)
187		case "assign":
188			err = cmdAssign(args[1:], stdout)
189		case "ticket":
190			err = cmdTicket(args[1:], stdout)
191		case "close":
192			err = cmdClose(args[1:], stdout)
193		case "cancel":
194			err = cmdCancel(args[1:], stdout)
195		case "plan":
196			err = cmdPlan(args[1:], stdout)
197		case "maintain":
198			err = cmdMaintain(args[1:], stdout)
199		case "due":
200			err = cmdDue(args[1:], stdout)
201		case "withdraw":
202			err = cmdWithdraw(args[1:], stdout)
203		case "return":
204			err = cmdReturn(args[1:], stdout)
205		case "history":
206			err = cmdHistory(args[1:], stdout)
207		case "downtime":
208			err = cmdDowntime(args[1:], stdout)
209		case "import":
210			err = cmdImport(args[1:], stdout)
211		default:
212			fmt.Fprintf(stderr, "%s: 未知命令 %q，使用 --help 查看帮助\n", appName, args[0])
213			return 2
214		}
215		if err != nil {
216			if errors.Is(err, flag.ErrHelp) {
217				return 0
218			}
219			var ue *usageError
220			if errors.As(err, &ue) {
221				fmt.Fprintf(stderr, "%s: %s\n", appName, ue.Error())
222				return 2
223			}
224			fmt.Fprintf(stderr, "%s: %s\n", appName, friendlyErr(err.Error()))
225			return 1
226		}
227		return 0
228	}
229	
230	// friendlyErr 去掉内部哨兵错误（errNotFound/errConflict）的英文前缀。
231	func friendlyErr(msg string) string {
232		for _, p := range []string{"not found: ", "conflict: "} {
233			if strings.HasPrefix(msg, p) {
234				return msg[len(p):]
235			}
236		}
237		return msg
238	}
239	
240	type usageError struct{ msg string }
241	
242	func (e *usageError) Error() string { return e.msg }
243	
244	// newFlagSet 为子命令准备参数解析器：--help/-h 输出帮助并返回 flag.ErrHelp，
245	// 其余参数错误转成 *usageError（退出码 2）。
246	func newFlagSet(name string, opts *cmdOptions) *flag.FlagSet {
247		fs := flag.NewFlagSet(name, flag.ContinueOnError)
248		fs.SetOutput(os.Stdout)
249		fs.Usage = func() {
250			fmt.Fprintf(os.Stdout, "用法: caretrack %s [参数]\n\n", name)
251			fs.PrintDefaults()
252		}
253		fs.StringVar(&opts.dataDir, "data-dir", ".caretrack", "本地数据目录")
254		return fs
255	}
256	
257	func parseFlags(fs *flag.FlagSet, args []string) error {
258		if err := fs.Parse(args); err != nil {
259			if errors.Is(err, flag.ErrHelp) {
260				return err
261			}
262			return &usageError{msg: err.Error()}
263		}
264		if fs.NArg() > 0 {
265			return &usageError{msg: fmt.Sprintf("命令 %s 不接受位置参数: %v", fs.Name(), fs.Args())}
266		}
267		return nil
268	}
269	
270	func requireFlag(fs *flag.FlagSet, value, flagName string) error {
271		if value == "" {
272			return &usageError{msg: fmt.Sprintf("命令 %s 缺少必填参数 --%s", fs.Name(), flagName)}
273		}
274		return nil
275	}
