277	func cmdRegister(args []string, w io.Writer) error {
278		var opts cmdOptions
279		var id, name, location string
280		fs := newFlagSet("register", &opts)
281		fs.StringVar(&id, "asset-id", "", "企业资产编号（必填，同一数据目录内唯一）")
282		fs.StringVar(&name, "name", "", "资产名称（必填）")
283		fs.StringVar(&location, "location", "", "资产位置（必填）")
284		if err := parseFlags(fs, args); err != nil {
285			return err
286		}
287		if err := requireFlag(fs, id, "asset-id"); err != nil {
288			return err
289		}
290		if err := requireFlag(fs, name, "name"); err != nil {
291			return err
292		}
293		if err := requireFlag(fs, location, "location"); err != nil {
294			return err
295		}
296	
297		s, err := openStore(opts.dataDir)
298		if err != nil {
299			return err
300		}
301		asset, err := s.registerAsset(id, name, location)
302		if err != nil {
303			return err
304		}
305		if err := s.save(); err != nil {
306			return err
307		}
308		fmt.Fprintf(w, "已登记资产 %s\n", asset.ID)
309		fmt.Fprintf(w, "名称: %s\n", asset.Name)
310		fmt.Fprintf(w, "位置: %s\n", asset.Location)
311		fmt.Fprintf(w, "当前状态: %s\n", asset.Status)
312		return nil
313	}
