315	func cmdList(args []string, w io.Writer) error {
316		var opts cmdOptions
317		fs := newFlagSet("list", &opts)
318		if err := parseFlags(fs, args); err != nil {
319			return err
320		}
321		s, err := openStore(opts.dataDir)
322		if err != nil {
323			return err
324		}
