337	func cmdDetail(args []string, w io.Writer) error {
338		var opts cmdOptions
339		var id string
340		fs := newFlagSet("detail", &opts)
341		fs.StringVar(&id, "asset-id", "", "企业资产编号（必填）")
342		if err := parseFlags(fs, args); err != nil {
343			return err
344		}
345		if err := requireFlag(fs, id, "asset-id"); err != nil {
346			return err
347		}
348		s, err := openStore(opts.dataDir)
349		if err != nil {
350			return err
351		}
352		asset := s.findAsset(id)
353		if asset == nil {
354			return fmt.Errorf("未知资产编号 %q", id)
355		}
356		openTicket := s.openTicketOf(asset.ID)
357		fmt.Fprintf(w, "资产编号: %s\n", asset.ID)
358		fmt.Fprintf(w, "名称: %s\n", asset.Name)
359		fmt.Fprintf(w, "位置: %s\n", asset.Location)
360		fmt.Fprintf(w, "当前状态: %s\n", asset.Status)
361		if openTicket == nil {
362			fmt.Fprintln(w, "未关闭工单: 无")
363		} else {
364			fmt.Fprintf(w, "未关闭工单: %s\n", openTicket.ID)
365			fmt.Fprintf(w, "工单负责人: %s\n", assigneeDisplay(openTicket.Assignee))
366		}
367		plan := s.findPlan(asset.ID)
368		if plan == nil {
369			fmt.Fprintln(w, "保养计划: 无")
370		} else {
371			fmt.Fprintf(w, "保养内容: %s\n", plan.Content)
372			fmt.Fprintf(w, "保养间隔: 每 %d 天\n", plan.IntervalDays)
373			fmt.Fprintf(w, "下一到期日: %s\n", plan.NextDue)
374		}
375		return nil
376	}
