386	func cmdReport(args []string, w io.Writer) error {
387		var opts cmdOptions
388		var assetID, description, requestID string
389		fs := newFlagSet("report", &opts)
390		fs.StringVar(&assetID, "asset-id", "", "企业资产编号（必填）")
391		fs.StringVar(&description, "description", "", "故障描述（必填）")
392		fs.StringVar(&requestID, "request-id", "", "调用方提供的非空请求标识，用于报修去重（必填）")
