840	// cmdDowntime 为只读的停机时长统计：先经 openStore 完成整库一致性检查，
841	// 再计算窗口内的停机秒数。无论成功或失败都不保存，因此不写文件、不初始化
842	// 目录、不追加履历、不消耗编号，也不改变报修请求绑定。
843	func cmdDowntime(args []string, w io.Writer) error {
844		var opts cmdOptions
845		var startText, endText, assetID string
846		fs := newFlagSet("downtime", &opts)
847		fs.StringVar(&startText, "start", "", "窗口起点（必填，带时区的 RFC3339 时刻，可含小数秒；包含）")
848		fs.StringVar(&endText, "end", "", "窗口终点（必填，带时区的 RFC3339 时刻，可含小数秒；不包含）")
849		fs.StringVar(&assetID, "asset-id", "", "企业资产编号（可选；缺省统计全部资产）")
850		if err := parseFlags(fs, args); err != nil {
851			return err
852		}
853		if err := requireFlag(fs, startText, "start"); err != nil {
854			return err
855		}
856		if err := requireFlag(fs, endText, "end"); err != nil {
857			return err
858		}
859		start, err := time.Parse(time.RFC3339, startText)
860		if err != nil {
861			return &usageError{msg: fmt.Sprintf("--start 不是带时区的 RFC3339 时刻 %q: %s", startText, err)}
862		}
863		end, err := time.Parse(time.RFC3339, endText)
864		if err != nil {
865			return &usageError{msg: fmt.Sprintf("--end 不是带时区的 RFC3339 时刻 %q: %s", endText, err)}
866		}
867		if !start.Before(end) {
868			return &usageError{msg: fmt.Sprintf("--start（%s）须早于 --end（%s）", startText, endText)}
869		}
870	
871		// openStore 已先做整库一致性检查：损坏或关联矛盾按原规则拒绝（退出码 1）。
872		s, err := openStore(opts.dataDir)
873		if err != nil {
874			return err
875		}
876	
877		var ids []string
878		if assetID != "" {
879			// 未知资产在统计前拒绝（退出码 1）。
880			if s.findAsset(assetID) == nil {
881				return fmt.Errorf("未知资产编号 %q", assetID)
882			}
883			ids = []string{assetID}
884		} else {
885			ids = s.allAssetIDs()
886			if len(ids) == 0 {
887				fmt.Fprintln(w, "没有记录。")
888				fmt.Fprintln(w, "合计: 0 秒")
889				return nil
890			}
891		}
892	
893		// 先算完全部结果再输出：任一资产存在时间异常时整体失败，不输出部分结果。
894		results, err := s.downtimeForAssets(ids, start, end)
895		if err != nil {
896			return err
897		}
898		var total int64
899		if len(results) == 1 {
900			r := results[0]
901			fmt.Fprintf(w, "资产编号: %s\n", r.AssetID)
902			fmt.Fprintf(w, "名称: %s\n", r.Name)
903			fmt.Fprintf(w, "停机秒数: %d\n", r.Seconds)
904			total = r.Seconds
905		} else {
906			fmt.Fprintf(w, "共 %d 项资产:\n", len(results))
907			for _, r := range results {
908				fmt.Fprintf(w, "%s\t%s\t%d\n", r.AssetID, r.Name, r.Seconds)
909				total += r.Seconds
910			}
911		}
912		fmt.Fprintf(w, "合计: %d 秒\n", total)
913		return nil
914	}
