402	// 失败重载：写入失败保留原文件字节、不留下部分记录、不消耗编号，恢复后可重试。
403	func TestPartSaveFailureLeavesFileUntouched(t *testing.T) {
404		s, dir := newPartStore(t)
405		if _, err := s.withdrawPart("T0001", "FILTER-01", 3, "更换滤芯"); err != nil {
406			t.Fatal(err)
407		}
408		mustSave(t, s)
409		before := readFileBytes(t, dir)
410	
411		if err := os.Chmod(dir, 0o555); err != nil {
412			t.Fatal(err)
413		}
414		s2, err := openStore(dir)
415		if err != nil {
416			t.Fatal(err)
417		}
418		if _, err := s2.withdrawPart("T0001", "ROLLER-02", 1, "搓纸轮"); err != nil {
419			t.Fatal(err)
420		}
421		saveErr := s2.save()
422		if cerr := os.Chmod(dir, 0o755); cerr != nil {
423			t.Fatal(cerr)
424		}
425		if saveErr == nil {
426			t.Skip("当前环境允许只读目录写入，跳过写入失败分支")
427		}
428		if string(readFileBytes(t, dir)) != string(before) {
429			t.Fatal("写入失败不应改动原文件字节")
430		}
431		// 重载后无部分记录、编号未消耗，恢复后可重试。
432		s3, err := openStore(dir)
433		if err != nil {
434			t.Fatalf("写入失败后应可正常重载: %v", err)
435		}
436		if len(s3.data.Parts) != 1 || s3.data.NextPartSeq != 2 {
437			t.Fatal("写入失败不应留下部分记录，也不应消耗领用编号")
438		}
439		p, err := s3.withdrawPart("T0001", "ROLLER-02", 1, "搓纸轮")
440		if err != nil || p.ID != "P0002" {
441			t.Fatalf("恢复后重试应分配 P0002: %v %+v", err, p)
442		}
443		mustSave(t, s3)
444	}
