446	// 命令行入口：参数错误退出 2，业务失败退出 1；ticket 按领用顺序显示各笔与
447	// 净量汇总（零值仍显示），history 展示领用、退回履历。
448	func TestPartCommandLine(t *testing.T) {
449		dir := t.TempDir()
450		var out, errOut bytes.Buffer
451		runCmd := func(args ...string) (int, string, string) {
452			out.Reset()
453			errOut.Reset()
454			code := run(append(args, "--data-dir", dir), &out, &errOut)
455			return code, out.String(), errOut.String()
456		}
457	
458		runCmd("register", "--asset-id", "EQ-1", "--name", "打印机", "--location", "一楼")
459		runCmd("report", "--asset-id", "EQ-1", "--description", "卡纸", "--request-id", "req-1")
460	
461		// 参数错误：缺说明、数量非正，退出 2。
462		if code, _, _ := runCmd("withdraw", "--ticket-id", "T0001", "--part-id", "F-1", "--quantity", "1"); code != 2 {
463			t.Fatalf("缺少 --note 应退出 2，得到 %d", code)
464		}
465		if code, _, _ := runCmd("withdraw", "--ticket-id", "T0001", "--part-id", "F-1", "--quantity", "0", "--note", "x"); code != 2 {
466			t.Fatalf("数量非正应退出 2，得到 %d", code)
467		}
468		// 业务失败：未知工单领用退出 1。
469		if code, _, _ := runCmd("withdraw", "--ticket-id", "T9999", "--part-id", "F-1", "--quantity", "1", "--note", "x"); code != 1 {
470			t.Fatalf("未知工单领用应退出 1，得到 %d", code)
471		}
472	
473		// 成功领用并输出领用编号。
474		code, o, _ := runCmd("withdraw", "--ticket-id", "T0001", "--part-id", "B-2", "--quantity", "2", "--note", "领用 B")
475		if code != 0 || !strings.Contains(o, "领用编号: P0001") {
476			t.Fatalf("领用应成功并输出 P0001，得到 %d:\n%s", code, o)
477		}
478		runCmd("withdraw", "--ticket-id", "T0001", "--part-id", "A-1", "--quantity", "1", "--note", "领用 A")
479		// 全部退回 A-1：净量零仍显示。
480		code, o, _ = runCmd("return", "--withdrawal-id", "P0002", "--quantity", "1", "--reason", "多余")
481		if code != 0 || !strings.Contains(o, "累计退回: 1") || !strings.Contains(o, "净量: 0") {
482			t.Fatalf("退回应显示累计退回与净量，得到 %d:\n%s", code, o)
483		}
484		// 超额退回退出 1。
485		if code, _, _ := runCmd("return", "--withdrawal-id", "P0001", "--quantity", "3", "--reason", "超额"); code != 1 {
486			t.Fatalf("超额退回应退出 1，得到 %d", code)
487		}
488		// 未知领用编号退出 1。
489		if code, _, _ := runCmd("return", "--withdrawal-id", "P9999", "--quantity", "1", "--reason", "x"); code != 1 {
490			t.Fatalf("未知领用编号应退出 1，得到 %d", code)
491		}
492	
493		// ticket：按领用顺序显示各笔，按备件编号字典序汇总，零值仍显示。
494		code, o, _ = runCmd("ticket", "--ticket-id", "T0001")
495		if code != 0 {
496			t.Fatalf("ticket 查询应成功，得到 %d", code)
497		}
498		i1 := strings.Index(o, "P0001\tB-2\t原数量 2\t累计退回 0\t净量 2")
499		i2 := strings.Index(o, "P0002\tA-1\t原数量 1\t累计退回 1\t净量 0")
500		if i1 < 0 || i2 < 0 || i1 > i2 {
501			t.Fatalf("ticket 应按领用顺序显示各笔记录，得到:\n%s", o)
502		}
503		s1 := strings.Index(o, "A-1\t净量 0")
504		s2 := strings.Index(o, "B-2\t净量 2")
505		if s1 < 0 || s2 < 0 || s1 > s2 {
506			t.Fatalf("ticket 应按备件编号字典序汇总净量（零值仍显示），得到:\n%s", o)
507		}
508	
509		// history：展示领用与退回履历。
510		code, o, _ = runCmd("history", "--asset-id", "EQ-1")
511		if code != 0 || !strings.Contains(o, "领用 工单 T0001: 领用编号 P0001，备件 B-2，数量 2（领用 B）") ||
512			!strings.Contains(o, "退回 工单 T0001: 领用编号 P0002，备件 A-1，数量 1（多余）") {
513			t.Fatalf("history 应展示领用与退回履历，得到 %d:\n%s", code, o)
514		}
515	
516		// 无记录明确提示。
517		runCmd("register", "--asset-id", "EQ-2", "--name", "空调", "--location", "二楼")
518		runCmd("report", "--asset-id", "EQ-2", "--description", "不制冷", "--request-id", "req-2")
519		code, o, _ = runCmd("ticket", "--ticket-id", "T0002")
520		if code != 0 || !strings.Contains(o, "备件领用: 无") {
521			t.Fatalf("无备件记录应明确提示，得到 %d:\n%s", code, o)
522		}
523	}
