		}, "状态矛盾"},
		{"未关闭工单带有维修结果", func(m map[string]any) {
			m["tickets"].([]any)[0].(map[string]any)["result"] = "已修复"
		}, "状态矛盾"},
		{"已关闭工单缺少维修结果", func(m map[string]any) {
			tk := m["tickets"].([]any)[0].(map[string]any)
			tk["status"] = "已关闭"
			tk["closed_at"] = "2026-10-01T11:00:00Z"
