		{"履历序号重复", func(m map[string]any) {
			appendTo(m, "events", eventJSONMap(3, "T0001", "报修", "卡纸"))
		}, "履历矛盾"},
		{"履历序号非正", func(m map[string]any) {
			m["events"].([]any)[0].(map[string]any)["seq"] = 0
