	var ticketID, path, note string
	fs := newFlagSet("attach", &opts)
	fs.StringVar(&ticketID, "ticket-id", "", "要登记附件的工单编号（必填；未关闭、已关闭或已取消工单均可）")
	fs.StringVar(&path, "path", "", "本地文件路径（必填；相对路径按当前工作目录解析，保存绝对路径；须为存在且可读的普通文件）")
