1	package main
2	
3	import (
4		"fmt"
5		"math"
6		"os"
7		"path/filepath"
8		"sort"
9	)
10	
11	// 维修工单附件的本地索引。
12	//
13	// 索引只保存资料文件的引用（绝对路径），不复制、修改或删除文件本身。
14	// 登记：输入工单编号、本地文件路径与非空说明；未关闭、已关闭或已取消工单均可
15	// 补充资料。相对路径按调用时工作目录解析并保存绝对路径；登记时须为存在且可读
16	// 的普通文件。每次登记独立生成同目录唯一且不复用的附件编号（A 加补零序号），
17	// 同路径不合并，也不使用报修请求标识去重。
18	//
19	// 撤销：输入附件编号与非空理由；成功后记录保留（路径、说明、理由都在），状态
20	// 变为已撤销。未知编号、重复撤销拒绝；不影响同路径的其他索引或后来的工单。
21	// 工单关闭或取消不自动撤销附件；已撤销编号不能恢复，可重新登记为新索引。
22	//
23	// 文件日后消失、成为目录或不可读，仅使该引用在查询时显示“不可用”，不阻止
24	// 撤销及其他任何业务，也不参与整库一致性校验。登记、撤销各为一次原子保存：
25	// 校验、编号或履历容量不足、读写失败时保留原文件字节，不留下部分记录、
26	// 不消耗编号，恢复后可重试。
27	
28	// findAttachment 按附件编号查找附件记录，不存在时返回 nil。
29	func (s *store) findAttachment(id string) *Attachment {
30		for _, a := range s.data.Attachments {
31			if a.ID == id {
32				return a
33			}
34		}
35		return nil
36	}
37	
38	// attachSeqs 返回每条附件编号对应的登记履历全库序号。附件编号只用于定位
39	// 记录：各条索引的先后由该条唯一登记履历的序号决定，与记录数组位置、编号
40	// 大小及履历时间无关（有效台账允许数组乱序、序号间隔、时间不递增）。
41	func (s *store) attachSeqs() map[string]int {
42		seqs := make(map[string]int, len(s.data.Attachments))
43		for _, e := range s.data.Events {
44			if e.Kind == eventAttach {
45				seqs[e.AttachmentID] = e.Seq
46			}
47		}
48		return seqs
49	}
50	
51	// attachmentsOf 按登记先后返回工单的全部附件索引（含已撤销）：顺序由每条
52	// 唯一登记履历的全库序号决定，不使用数组位置或编号大小。
53	func (s *store) attachmentsOf(ticketID string) []*Attachment {
54		seqs := s.attachSeqs()
55		out := make([]*Attachment, 0)
56		for _, a := range s.data.Attachments {
57			if a.TicketID == ticketID {
58				out = append(out, a)
59			}
60		}
61		sort.SliceStable(out, func(i, j int) bool { return seqs[out[i].ID] < seqs[out[j].ID] })
62		return out
63	}
64	
65	// regularFileReadable 报告路径当前是否指向一个存在且可读的普通文件。
66	// 目录、不存在或不可读的路径都返回 false。只读检查，不修改任何文件。
67	func regularFileReadable(path string) bool {
68		f, err := os.Open(path)
69		if err != nil {
70			return false
71		}
72		defer func() { _ = f.Close() }()
73		fi, err := f.Stat()
74		if err != nil {
75			return false
76		}
77		return fi.Mode().IsRegular()
78	}
79	
80	// appendAttachEvent 以给定序号追加附件履历（登记或撤销）。附件履历属于附件
81	// 记录所在的工单，from/to、保养与备件字段恒为空；content 为登记说明或撤销理由。
82	func (s *store) appendAttachEvent(seq int, a *Attachment, kind, content string) {
83		s.data.Events = append(s.data.Events, Event{
84			Seq:          seq,
85			AssetID:      a.AssetID,
86			TicketID:     a.TicketID,
87			Kind:         kind,
88			Content:      content,
89			AttachmentID: a.ID,
90			Path:         a.Path,
91			Time:         s.now(),
92		})
93	}
94	
95	// attachFile 为工单登记一条附件索引：相对路径按调用时工作目录解析并保存
96	// 绝对路径，登记时文件须为存在且可读的普通文件。未关闭、已关闭或已取消工单
97	// 均可登记。每次登记独立生成同目录唯一且不复用的附件编号，同路径不合并，
98	// 不使用报修请求标识去重。失败路径不修改任何业务数据，也不消耗附件编号。
99	func (s *store) attachFile(ticketID, path, note string) (*Attachment, error) {
100		t := s.findTicket(ticketID)
101		if t == nil {
102			return nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
103		}
104		if note == "" {
105			return nil, fmt.Errorf("%w: 附件说明不能为空", errConflict)
106		}
107		abs, err := filepath.Abs(path)
108		if err != nil {
109			return nil, fmt.Errorf("无法解析文件路径 %q: %w", path, err)
110		}
111		if !regularFileReadable(abs) {
112			return nil, fmt.Errorf("%w: 文件 %s 不存在、不是普通文件或不可读，不能登记为附件", errConflict, abs)
113		}
114		// 先确认附件编号与履历计数器都能推进，再修改任何业务数据：
115		// 编号耗尽时拒绝登记，不消耗编号，也不产生履历。
116		seq := s.data.NextAttachSeq
117		if seq < 1 || seq == math.MaxInt {
118			return nil, fmt.Errorf("%w: 附件编号计数器已耗尽，无法分配新附件编号", errConflict)
119		}
120		eventSeq, err := s.nextEventSeq()
121		if err != nil {
122			return nil, err
123		}
124		a := &Attachment{
125			ID:       fmt.Sprintf("A%04d", seq),
126			TicketID: t.ID,
127			AssetID:  t.AssetID,
128			Path:     abs,
129			Note:     note,
130		}
131		s.data.NextAttachSeq = seq + 1
132		s.data.Attachments = append(s.data.Attachments, a)
133		s.appendAttachEvent(eventSeq, a, eventAttach, note)
134		return a, nil
135	}
136	
137	// revokeAttachment 按附件编号撤销一条索引：记录、路径、说明与理由全部保留，
138	// 状态变为已撤销。撤销与工单状态、文件当前可用性无关；不影响同路径的其他
139	// 索引。已撤销编号不能恢复，也不能再次撤销。失败路径不修改任何业务数据。
140	func (s *store) revokeAttachment(id, reason string) (*Attachment, error) {
141		a := s.findAttachment(id)
142		if a == nil {
143			return nil, fmt.Errorf("%w: 未知附件编号 %q", errNotFound, id)
144		}
145		if a.Revoked {
146			return nil, fmt.Errorf("%w: 附件 %s 已撤销，不能重复撤销", errConflict, id)
147		}
148		if reason == "" {
149			return nil, fmt.Errorf("%w: 撤销理由不能为空", errConflict)
150		}
151		eventSeq, err := s.nextEventSeq()
152		if err != nil {
153			return nil, err
154		}
155		a.Revoked = true
156		a.RevokeReason = reason
157		s.appendAttachEvent(eventSeq, a, eventRevoke, reason)
158		return a, nil
159	}

input.content:
package main

import (
	"bytes"
	"encoding/json"
	"errors"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// writeFile 在目录下建立指定内容的资料文件，返回其绝对路径。
func writeFile(t *testing.T, dir, name, content string) string {
	t.Helper()
	p := filepath.Join(dir, name)
	if err := os.WriteFile(p, []byte(content), 0o644); err != nil {
		t.Fatal(err)
	}
	return p
}

// newAttachStore 建立含一项资产与一张未关闭工单 T0001 的测试台账。
func newAttachStore(t *testing.T) (*store, string) {
	t.Helper()
	dir := t.TempDir()
	s := newStoreAt(t, dir)
	if _, err := s.registerAsset("EQ-1", "打印机", "一楼"); err != nil {
		t.Fatal(err)
	}
	if _, _, err := s.report("EQ-1", "卡纸", "req-1"); err != nil { // T0001
		t.Fatal(err)
	}
	mustSave(t, s)
	return s, dir
}

// 登记与撤销：各状态工单均可登记；同路径不合并；撤销保留记录、路径、说明与理由；
// 未知编号、重复撤销拒绝；已撤销编号不能恢复，可重新登记为新索引；重载后保持。
func TestAttachAndRevoke(t *testing.T) {
	s, dir := newAttachStore(t)
	fileDir := t.TempDir()
	f1 := writeFile(t, fileDir, "manual.pdf", "v1")
	f2 := writeFile(t, fileDir, "photo.jpg", "v2")

	// 未关闭工单登记；同路径再次登记各自独立，不合并。
	a1, err := s.attachFile("T0001", f1, "维修手册")
	if err != nil || a1.ID != "A0001" {
		t.Fatalf("首次登记: %v %+v", err, a1)
	}
	if a1.Path != f1 || !filepath.IsAbs(a1.Path) {
		t.Fatalf("保存的应为绝对路径: %q", a1.Path)
	}
	a2, err := s.attachFile("T0001", f1, "同一手册另一索引")
	if err != nil || a2.ID != "A0002" {
		t.Fatalf("同路径应独立登记为 A0002: %v %+v", err, a2)
	}
	// 空说明拒绝。
	if _, err := s.attachFile("T0001", f2, ""); err == nil {
		t.Fatal("空说明应拒绝")
	}
	// 未知工单拒绝。
	if _, err := s.attachFile("T9999", f2, "x"); !errors.Is(err, errNotFound) {
		t.Fatalf("未知工单应拒绝，得到 %v", err)
	}
	mustSave(t, s)

	// 已关闭工单也可补充资料。
	if _, _, err := s.closeTicket("T0001", "已修复"); err != nil {
		t.Fatal(err)
	}
	a3, err := s.attachFile("T0001", f2, "现场照片")
	if err != nil || a3.ID != "A0003" {
		t.Fatalf("已关闭工单登记: %v %+v", err, a3)
	}
	// 已取消工单同样可补充资料。
	if _, _, err := s.report("EQ-1", "无法开机", "req-2"); err != nil { // T0002
		t.Fatal(err)
	}
	if _, _, err := s.cancelTicket("T0002", "误报"); err != nil {
		t.Fatal(err)
	}
	a4, err := s.attachFile("T0002", f2, "取消工单的照片")
	if err != nil || a4.ID != "A0004" {
		t.Fatalf("已取消工单登记: %v %+v", err, a4)
	}
	mustSave(t, s)

	// 撤销：保留记录、路径、说明与理由。
	got, err := s.revokeAttachment("A0001", "手册版本过期")
	if err != nil {
		t.Fatal(err)
	}
	if !got.Revoked || got.RevokeReason != "手册版本过期" ||
		got.Path != f1 || got.Note != "维修手册" {
		t.Fatalf("撤销后记录应完整保留: %+v", got)
	}
	// 重复撤销与未知编号拒绝；空理由拒绝。
	if _, err := s.revokeAttachment("A0001", "再次"); !errors.Is(err, errConflict) {
		t.Fatalf("重复撤销应拒绝，得到 %v", err)
	}
	if _, err := s.revokeAttachment("A9999", "x"); !errors.Is(err, errNotFound) {
		t.Fatalf("未知附件编号应拒绝，得到 %v", err)
	}
	if _, err := s.revokeAttachment("A0002", ""); err == nil {
		t.Fatal("空撤销理由应拒绝")
	}
	// 撤销不影响同路径的其他索引。
	if s.findAttachment("A0002").Revoked {
		t.Fatal("撤销 A0001 不应影响同路径的 A0002")
	}
	// 已撤销编号不能恢复，同路径可重新登记为新索引。
	a5, err := s.attachFile("T0001", f1, "手册新版")
	if err != nil || a5.ID != "A0005" {
		t.Fatalf("撤销后同路径重新登记应为新编号 A0005: %v %+v", err, a5)
	}
	mustSave(t, s)

	// 重载后索引状态与编号延续保持。
	s2, err := openStore(dir)
	if err != nil {
		t.Fatalf("重载: %v", err)
	}
	r1 := s2.findAttachment("A0001")
	if r1 == nil || !r1.Revoked || r1.RevokeReason != "手册版本过期" || r1.Note != "维修手册" {
		t.Fatalf("重载后 A0001 撤销状态未保持: %+v", r1)
	}
	if s2.data.NextAttachSeq != 6 {
		t.Fatalf("下一附件序号 = %d, 想得到 6", s2.data.NextAttachSeq)
	}
	a6, err := s2.attachFile("T0002", f1, "继续登记")
	if err != nil || a6.ID != "A0006" {
		t.Fatalf("重载后编号应延续为 A0006: %v %+v", err, a6)
	}
	mustSave(t, s2)

	// attachmentsOf 按登记履历序号排序，含已撤销。
	list := s2.attachmentsOf("T0001")
	if len(list) != 4 || list[0].ID != "A0001" || list[1].ID != "A0002" ||
		list[2].ID != "A0003" || list[3].ID != "A0005" {
		t.Fatalf("附件顺序应为登记顺序: %+v", list)
	}
}

// 文件失联：登记后文件消失或成为目录仅使引用不可用，不阻止撤销及其他业务；
// 登记时文件不存在、为目录或不可读均拒绝。
func TestAttachFileAvailability(t *testing.T) {
	s, dir := newAttachStore(t)
	fileDir := t.TempDir()
	f1 := writeFile(t, fileDir, "doc.txt", "x")

	// 登记时不存在的路径、目录均拒绝。
	if _, err := s.attachFile("T0001", filepath.Join(fileDir, "nope.txt"), "不存在"); err == nil {
		t.Fatal("不存在的文件应拒绝登记")
	}
	if _, err := s.attachFile("T0001", fileDir, "目录"); err == nil {
		t.Fatal("目录应拒绝登记")
	}
	if len(s.data.Attachments) != 0 || s.data.NextAttachSeq != 1 {
		t.Fatal("失败的登记不应留下记录或消耗编号")
	}

	if _, err := s.attachFile("T0001", f1, "文档"); err != nil {
		t.Fatal(err)
	}
	mustSave(t, s)

	// 文件消失：引用变为不可用，但台账仍一致，撤销及其他业务不受影响。
	if err := os.Remove(f1); err != nil {
		t.Fatal(err)
	}
	if regularFileReadable(f1) {
		t.Fatal("文件删除后应不可用")
	}
	s2, err := openStore(dir)
	if err != nil {
		t.Fatalf("文件消失不应影响台账加载: %v", err)
	}
	if _, err := s2.revokeAttachment("A0001", "文件已清理"); err != nil {
		t.Fatalf("文件消失不应阻止撤销: %v", err)
	}
	// 其他业务不受影响：关闭工单。
	if _, _, err := s2.closeTicket("T0001", "已修复"); err != nil {
		t.Fatalf("文件消失不应影响关闭工单: %v", err)
	}
	mustSave(t, s2)

	// 路径成为目录同样仅使引用不可用。
	f2 := writeFile(t, fileDir, "pic.bin", "y")
	if _, err := s2.attachFile("T0001", f2, "照片"); err != nil {
		t.Fatal(err)
	}
	if err := os.Remove(f2); err != nil {
		t.Fatal(err)
	}
	if err := os.Mkdir(f2, 0o755); err != nil {
		t.Fatal(err)
	}
	if regularFileReadable(f2) {
		t.Fatal("目录应视为不可用")
	}
	if _, err := openStore(dir); err != nil {
		t.Fatalf("路径成为目录不应影响台账加载: %v", err)
	}
}

// 无附件字段的有效旧库直接使用：缺省视为没有附件索引，附件编号从 A0001 开始。
func TestLegacyStoreWithoutAttachments(t *testing.T) {
